INSERT INTO destinations (name, country, description, temperature_avg, best_time_to_visit, currency, language, latitude, longitude, travel_type, budget_category, average_rating, review_count, image_url) VALUES
('Agra - Taj Mahal',              'India', 'Home to the iconic Taj Mahal, one of the Seven Wonders of the World. Agra is a city steeped in Mughal history with magnificent forts and palaces.',                                                        25, 'October to March',                              'INR', 'Hindi',              27.1767, 78.0081, 'Cultural',   'MidRange', 4.8, 0, 'https://images.unsplash.com/photo-1564507592333-c60657eea523?w=600'),
('Goa',                           'India', 'India''s beach paradise with golden shores, turquoise waters, vibrant nightlife, and a unique blend of Indian and Portuguese culture.',                                                                    27, 'November to February',                          'INR', 'Konkani, English',   15.2993, 74.1240, 'Beach',      'Budget',   4.6, 0, 'https://images.unsplash.com/photo-1512343879784-a960bf40e7f2?w=600'),
('Jaipur - Pink City',            'India', 'The Pink City of Rajasthan famous for Hawa Mahal, Amer Fort, and City Palace. A stunning blend of royal heritage and vibrant bazaars.',                                                                    25, 'October to March',                              'INR', 'Hindi, Rajasthani',  26.9124, 75.7873, 'Cultural',   'MidRange', 4.7, 0, 'https://images.unsplash.com/photo-1477587458883-47145ed94245?w=600'),
('Kerala Backwaters',             'India', 'A serene network of lagoons, lakes, and canals in God''s Own Country. Houseboat cruises through lush paddy fields and coconut groves are unmissable.',                                                     27, 'September to March',                            'INR', 'Malayalam',          9.4981,  76.3388, 'Nature',     'MidRange', 4.7, 0, 'https://images.unsplash.com/photo-1602216056096-3b40cc0c9944?w=600'),
('Varanasi',                      'India', 'One of the world''s oldest living cities on the banks of the Ganges. Experience spiritual rituals, ancient ghats, and the eternal cycle of life and death.',                                               24, 'October to March',                              'INR', 'Hindi',              25.3176, 82.9739, 'Cultural',   'Budget',   4.5, 0, 'https://images.unsplash.com/photo-1561361513-2d8efce50688?w=600'),
('Leh Ladakh',                    'India', 'High-altitude desert landscape with ancient monasteries, turquoise lakes, and dramatic mountain passes. A dream for adventure seekers and motorcyclists.',                                                   5,  'June to September',                             'INR', 'Ladakhi, Hindi',     34.1526, 77.5771, 'Adventure',  'MidRange', 4.9, 0, 'https://images.unsplash.com/photo-1626621341517-bbf3d9990a23?w=600'),
('Rishikesh',                     'India', 'The Yoga Capital of the World situated on the banks of the Ganges. Famous for white-water rafting, bungee jumping, yoga retreats, and spiritual ashrams.',                                                  20, 'February to May, September to November',        'INR', 'Hindi',              30.0869, 78.2676, 'Adventure',  'Budget',   4.6, 0, 'https://images.unsplash.com/photo-1600100397608-c13e3e23e3c7?w=600'),
('Shimla',                        'India', 'The Queen of Hill Stations in the Himalayas, former summer capital of British India. Charming colonial architecture, scenic toy trains, and snow-capped views.',                                             12, 'March to June, December to February (snow)',    'INR', 'Hindi',              31.1048, 77.1734, 'Mountain',   'MidRange', 4.5, 0, 'https://images.unsplash.com/photo-1573158754104-b7e2b2430eca?w=600'),
('Udaipur - City of Lakes',       'India', 'The most romantic city in India, surrounded by Aravalli hills and glittering lakes. Magnificent palaces, ornate temples, and lakeside heritage hotels.',                                                    24, 'October to March',                              'INR', 'Hindi, Rajasthani',  24.5854, 73.7125, 'Cultural',   'Luxury',   4.8, 0, 'https://images.unsplash.com/photo-1598091383021-15ddea10925d?w=600'),
('Manali',                        'India', 'A high-altitude Himalayan resort town famous for adventure sports, snow peaks, ancient temples, and the gateway to Rohtang Pass and Spiti Valley.',                                                          8,  'October to June (snow), July to September (adventure)', 'INR', 'Hindi, Kullu', 32.2396, 77.1887, 'Mountain', 'MidRange', 4.6, 0, 'https://images.unsplash.com/photo-1580289144113-4b8a35a1c09a?w=600'),
('Darjeeling',                    'India', 'The Land of the Thunderbolt with sweeping views of Kanchenjunga, famous tea plantations, the Darjeeling Himalayan Railway (UNESCO), and colonial charm.',                                                  12, 'March to May, September to November',           'INR', 'Bengali, Nepali',    27.0410, 88.2663, 'Mountain',   'Budget',   4.5, 0, 'https://images.unsplash.com/photo-1623943491053-4a2c4f89f7d0?w=600'),
('Hampi',                         'India', 'A UNESCO World Heritage Site and the ruins of the Vijayanagara Empire. Boulder-strewn landscape with stunning temples, bazaars, and chariot streets.',                                                      27, 'October to February',                           'INR', 'Kannada',            15.3350, 76.4600, 'Cultural',   'Budget',   4.7, 0, 'https://images.unsplash.com/photo-1600697230053-c3e4ef7e0b73?w=600'),
('Andaman Islands',               'India', 'Pristine tropical islands in the Bay of Bengal with white sandy beaches, coral reefs, and crystal-clear waters perfect for snorkeling and scuba diving.',                                                   26, 'October to May',                                'INR', 'Hindi, Bengali',     11.7401, 92.6586, 'Beach',      'MidRange', 4.8, 0, 'https://images.unsplash.com/photo-1518509562904-e7ef99cdcc86?w=600'),
('Munnar',                        'India', 'A misty hill station in Kerala blanketed by rolling tea plantations, spice gardens, and lush forests. Home to the rare Neelakurinji flower.',                                                              15, 'September to March',                            'INR', 'Malayalam',          10.0889, 77.0595, 'Nature',     'MidRange', 4.6, 0, 'https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=600'),
('Mysore',                        'India', 'The City of Palaces in Karnataka, famous for the stunning Mysore Palace, Chamundi Hills, silk sarees, and the grand Dasara celebrations.',                                                                  25, 'October to February',                           'INR', 'Kannada',            12.2958, 76.6394, 'Cultural',   'MidRange', 4.5, 0, 'https://images.unsplash.com/photo-1571536802807-30451e3955d8?w=600'),
('Coorg',                         'India', 'Scotland of India nestled in the Western Ghats. Lush coffee and spice plantations, misty hills, waterfalls, and vibrant Kodava culture.',                                                                   20, 'October to March',                              'INR', 'Kodava, Kannada',    12.3375, 75.8069, 'Nature',     'MidRange', 4.6, 0, 'https://images.unsplash.com/photo-1587474260584-136574528ed5?w=600'),
('Ooty',                          'India', 'The Queen of Hill Stations in Tamil Nadu with tea gardens, botanical gardens, and the scenic Nilgiri Mountain Railway. Perfect escape from summer heat.',                                                   15, 'April to June, September to November',          'INR', 'Tamil',              11.4102, 76.6950, 'Mountain',   'Budget',   4.4, 0, 'https://images.unsplash.com/photo-1596402184320-417e7178b2cd?w=600'),
('Ranthambore National Park',     'India', 'One of India''s best wildlife sanctuaries, famous for its Bengal tiger population. Historic Ranthambore Fort within the park adds to its mystique.',                                                        25, 'October to June',                               'INR', 'Hindi, Rajasthani',  26.0173, 76.5026, 'Nature',     'MidRange', 4.7, 0, 'https://images.unsplash.com/photo-1602491453631-e2a5ad90a131?w=600'),
('Pondicherry',                   'India', 'A former French colony with charming colonial architecture, tranquil ashrams, pristine beaches, and a unique blend of French and Tamil cultures.',                                                           28, 'October to March',                              'INR', 'Tamil, French',      11.9416, 79.8083, 'Beach',      'Budget',   4.4, 0, 'https://images.unsplash.com/photo-1582531865817-b8bb4c9e1e1f?w=600'),
('Mahabalipuram',                 'India', 'UNESCO World Heritage coastal town known for its 7th-century rock-cut temples, Shore Temple, and the famous Descent of the Ganges bas-relief.',                                                             28, 'October to March',                              'INR', 'Tamil',              12.6269, 80.1927, 'Cultural',   'Budget',   4.4, 0, 'https://images.unsplash.com/photo-1609512601671-dc2e1b80bbb6?w=600'),
('Kolkata',                       'India', 'The City of Joy and cultural capital of India. Victoria Memorial, Howrah Bridge, colonial architecture, intellectual heritage, and amazing street food.',                                                    26, 'October to March',                              'INR', 'Bengali',            22.5726, 88.3639, 'Cultural',   'Budget',   4.3, 0, 'https://images.unsplash.com/photo-1558431382-27e303142255?w=600'),
('Mumbai',                        'India', 'The Maximum City and financial capital of India. Gateway of India, Marine Drive, Bollywood, street food, and the perfect blend of old and modern.',                                                          27, 'November to February',                          'INR', 'Hindi, Marathi',     19.0760, 72.8777, 'Cultural',   'MidRange', 4.5, 0, 'https://images.unsplash.com/photo-1570168007204-dfb528c6958f?w=600'),
('Delhi',                         'India', 'India''s capital with incredible Mughal monuments including Red Fort, Qutub Minar, Humayun''s Tomb, vibrant markets, and world-class dining.',                                                             24, 'October to March',                              'INR', 'Hindi',              28.7041, 77.1025, 'Cultural',   'MidRange', 4.4, 0, 'https://images.unsplash.com/photo-1587474260584-136574528ed5?w=600'),
('Jaisalmer - Golden City',       'India', 'The Golden City rising from the Thar Desert with a magnificent sandstone fort, ornate havelis, and magical camel safaris under starry skies.',                                                              28, 'October to February',                           'INR', 'Hindi, Rajasthani',  26.9157, 70.9083, 'Adventure',  'MidRange', 4.7, 0, 'https://images.unsplash.com/photo-1604608672516-5b9a8e6b3d3d?w=600'),
('Amritsar',                      'India', 'Home to the magnificent Golden Temple, the holiest shrine of Sikhism. The Wagah Border ceremony and Jallianwala Bagh add historical depth.',                                                                22, 'October to March',                              'INR', 'Punjabi, Hindi',     31.6340, 74.8723, 'Cultural',   'Budget',   4.7, 0, 'https://images.unsplash.com/photo-1609952542840-df54cfdefa2d?w=600'),
('Spiti Valley',                  'India', 'A remote cold desert mountain valley in the Himalayas. Ancient Buddhist monasteries, barren landscapes, and star-studded skies make it unique.',                                                             2,  'June to October',                               'INR', 'Spitian, Hindi',     32.2461, 78.0322, 'Adventure',  'Budget',   4.8, 0, 'https://images.unsplash.com/photo-1566837486754-44a6d7c16b58?w=600'),
('Pushkar',                       'India', 'A sacred city in Rajasthan built around the holy Pushkar Lake. Famous for the world''s only Brahma temple and the largest camel fair on earth.',                                                            25, 'October to March',                              'INR', 'Hindi, Rajasthani',  26.4899, 74.5511, 'Cultural',   'Budget',   4.4, 0, 'https://images.unsplash.com/photo-1598091383021-15ddea10925d?w=600'),
('Hyderabad',                     'India', 'The City of Pearls and Nizams with magnificent Charminar, Golconda Fort, legendary biryani, and a booming IT sector meeting ancient culture.',                                                              27, 'October to February',                           'INR', 'Telugu, Urdu',       17.3850, 78.4867, 'Cultural',   'MidRange', 4.4, 0, 'https://images.unsplash.com/photo-1552832230-c0197dd311b5?w=600'),
('Alleppey - Venice of the East', 'India', 'The Venice of the East with extensive canal networks, charming houseboats drifting through emerald backwaters, and beautiful beaches.',                                                                     27, 'November to February',                          'INR', 'Malayalam',          9.4981,  76.3388, 'Nature',     'Budget',   4.6, 0, 'https://images.unsplash.com/photo-1602216056096-3b40cc0c9944?w=600'),
('Jim Corbett National Park',     'India', 'India''s oldest national park in the Himalayan foothills, famous for Bengal tigers, Asian elephants, leopards, and rich birdlife amid dense forests.',                                                     20, 'November to June',                              'INR', 'Hindi',              29.5300, 78.7747, 'Nature',     'MidRange', 4.6, 0, 'https://images.unsplash.com/photo-1561715276-a2d087060f1d?w=600');
